class Solution {
  public long maxSum(int[] nums, int k, int mul) {
    int[] count = new int[100001];
    for (int x : nums) count[x]++;
    long sum = 0;
    int taken = 0;
    // the k largest values, biggest first, so they meet the biggest multipliers
    for (int v = 100000; v >= 1 && taken < k; v--) {
      for (int c = count[v]; c > 0 && taken < k; c--, taken++) {
        sum += (long) v * Math.max(1, mul - taken);
      }
    }
    return sum;
  }
}
